GrowthInGroups.Lecture3.proposition_3_6_2.{u_1} {G : Type u_1} [Group G] {A B : Set G} {K L : ℝ} {m n : ℕ}
  (hA : IsApproximateSubgroup K A) (hB : IsApproximateSubgroup L B) (hm : 2 ≤ m) (hn : 2 ≤ n) :
  IsApproximateSubgroup (K ^ (2 * m - 1) * L ^ (2 * n - 1)) (A ^ m ∩ B ^ n)

GrowthInGroups.Lecture1.lemma_1_11.{u_1} {G : Type u_1} [Group G] [DecidableEq G] {A : Finset G}
  (hA : ↑(Finset.card (A * A)) < 3 / 2 * ↑(Finset.card A)) :
  ∃ H x, ↑(Fintype.card ↥H) < 3 / 2 * ↑(Finset.card A) ∧ ∀ a ∈ A, ↑A ⊆ a • ↑H ∧ a • ↑H = MulOpposite.op a • ↑H

GrowthInGroups.Lecture3.proposition_3_6_1.{u_1} {G : Type u_1} [Group G] {A B : Set G} {K L : ℝ} {m n : ℕ}
  (hA : IsApproximateSubgroup K A) (hB : IsApproximateSubgroup L B) (hm : 2 ≤ m) (hn : 2 ≤ n) :
  ∃ F, ↑(Finset.card F) ≤ K ^ (m - 1) * L ^ (n - 1) ∧ A ^ m ∩ B ^ n ⊆ ↑F * (A ^ 2 ∩ B ^ 2)

GrowthInGroups.Lecture3.theorem_4_5.{u_2} {C : ℝ} {G : Type u_2} [Group G] [DecidableEq G] {S : Finset G}
  (hSsymm : S⁻¹ = S) (hSgen : ↑(Subgroup.closure ↑S) = Set.univ) {d : ℕ}
  (hS : ∀ (n : ℕ), ↑(Finset.card (S ^ n)) ≤ C * ↑n ^ d) : Group.IsVirtuallyNilpotent G
